    text: `<strong>Passage A: Coral Gardening, A Reason for Hope</strong><br><br>Over the past decade, marine biologists have developed increasingly sophisticated techniques for growing coral fragments in underwater nurseries before transplanting them onto damaged reefs. In the Florida Keys, one nonprofit organization has outplanted more than 200,000 coral fragments since 2007, focusing on fast-growing staghorn and elkhorn species that were once common throughout the Caribbean but have declined by more than 90 percent since the 1980s. Early results have been encouraging: surveys of restored reef sections show coral cover increasing from under five percent to as much as thirty percent within five years at the most successful sites, providing habitat for fish populations that had largely disappeared from those areas. Advocates argue that while restoration cannot address the root causes of reef decline, such as rising ocean temperatures, it can buy critical time for reefs to survive long enough for broader climate solutions to take effect, and that the techniques developed through this work are improving rapidly enough to be applied at increasingly larger scales.<br><br><strong>Passage B: Why Coral Restoration Won't Save the Reefs</strong><br><br>Some marine scientists remain skeptical that coral gardening can meaningfully address the scale of global reef decline. Roughly half of the world's coral reefs have been lost since 1950, primarily due to warming ocean temperatures, and restoration projects, however successful locally, currently plant coral across only a tiny fraction of the reef area lost each year. Critics point out that transplanted coral remains just as vulnerable to marine heatwaves as naturally occurring coral, and that a single severe bleaching event can kill transplanted fragments as quickly as it kills wild colonies, sometimes erasing years of restoration work in a matter of weeks. Because restoration projects tend to be expensive and labor-intensive, expanding them to a scale that could offset global reef loss would require a level of funding and coordination that no country or organization has yet committed to providing. Rather than treating coral gardening as a solution, these critics argue, policymakers should treat it as a limited, supplementary tool, one that must be paired with aggressive action on ocean warming if reefs are to survive this century at all.`,
